"""Биология, вторая часть (№22, 23, 25-28). Все ответы развёрнутые, их оценивает соперник.

№24 пропущен: для него нужен рисунок, а экран проверки рисунков не показывает.
"""

from exam_common import Entry, essay, essays

THREE = ["3 балла: ответ включает все элементы эталона (смысл может быть передан другими словами) и не содержит биологических ошибок.",
         "2 балла: в ответе на один элемент меньше, чем в эталоне, либо есть все элементы, но допущена биологическая ошибка.",
         "1 балл: верно приведён только один элемент ответа (в задачах: верно выполнена только часть решения).",
         "0 баллов: ответ неверный."]


def make(items):
    return [essay(text, solution, THREE) for text, solution in items]


